// Calculate today's date in YYYY-MM-DD format
const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');
return [{ json: { fecha_hoy: `${yyyy}-${mm}-${dd}` } }];

const orders = $('Read Today Orders').all();
const details = $('Read Detail Lines').all();

// Total sales
const totalVentas = orders.reduce((sum, o) => sum + parseFloat(o.json.total_pago || 0), 0);
const numPedidos = orders.length;

// Product star (most sold)
const productCount = {};
details.forEach(d => {
  const name = d.json.nombre;
  const qty = parseInt(d.json.cantidad || 0);
  productCount[name] = (productCount[name] || 0) + qty;
});
const sorted = Object.entries(productCount).sort((a, b) => b[1] - a[1]);
const productoEstrella = sorted[0] ? sorted[0][0] : 'N/A';
const cantidadEstrella = sorted[0] ? sorted[0][1] : 0;

// Peak hour
const hourCount = {};
orders.forEach(o => {
  const hour = (o.json.hora || '00:00').split(':')[0];
  hourCount[hour] = (hourCount[hour] || 0) + 1;
});
const peakHour = Object.entries(hourCount).sort((a, b) => b[1] - a[1])[0];
const horaPico = peakHour ? `${peakHour[0]}:00-${parseInt(peakHour[0]) + 1}:00` : 'N/A';

return [{
  json: {
    fecha: new Date().toISOString().slice(0, 10),
    total_ventas: totalVentas.toFixed(2),
    num_pedidos: numPedidos,
    producto_estrella: productoEstrella,
    cantidad_estrella: cantidadEstrella,
    hora_pico: horaPico,
    generado_en: new Date().toISOString()
  }
}];

// Filter menu items with low stock
const menuItems = $('Read All Menu Items').all();
const lowStock = menuItems.filter(item => {
  const stock = parseInt(item.json.stock || 0);
  const stockMinimo = parseInt(item.json.stock_minimo || 0);
  const activo = String(item.json.activo).toUpperCase();
  return stock <= stockMinimo && (activo === 'TRUE' || activo === 'SI' || activo === '1');
});

return [{
  json: {
    low_stock_items: lowStock.map(item => ({
      nombre: item.json.nombre,
      stock: parseInt(item.json.stock || 0)
    }))
  }
}];

// Format the daily report message
const metrics = $('Calculate Metrics').first().json;
const lowStockData = $('Check Low Stock').first().json.low_stock_items;

let lowStockSection = '';
if (lowStockData && lowStockData.length > 0) {
  const lines = lowStockData.map(item => `• ${item.nombre}: ${item.stock} restantes`);
  lowStockSection = `\n\n⚠️ *Productos con Stock Bajo:*\n${lines.join('\n')}`;
} else {
  lowStockSection = '\n\n✅ *Stock:* Todos los productos tienen stock suficiente.';
}

const report = `📊 *REPORTE DIARIO — ${metrics.fecha}*\n\n` +
  `💰 Total Vendido: $${metrics.total_ventas}\n` +
  `📦 Pedidos Completados: ${metrics.num_pedidos}\n` +
  `⭐ Producto Estrella: ${metrics.producto_estrella} (${metrics.cantidad_estrella} uds)\n` +
  `🕐 Hora Pico: ${metrics.hora_pico}` +
  lowStockSection +
  `\n\n🕐 _Generado: ${metrics.generado_en}_`;

return [{ json: { report } }];
